tool.command:
ln -s $input_model_pth_path ./input_model_pth_path.$input_model_pth_path.ext; #if $input_stats_pt_path: ln -s $input_stats_pt_path ./input_stats_pt_path.$input_stats_pt_path.ext; #end if #if $input_reference_pdb_path: ln -s $input_reference_pdb_path ./input_reference_pdb_path.$input_reference_pdb_path.ext; #end if #if $input_ndx_path: ln -s $input_ndx_path ./input_ndx_path.$input_ndx_path.ext; #end if #if $config_json: ln -s $config_json ./config_json.$config_json.ext; #end if
make_plumed
#if $config_json: --config ./config_json.$config_json.ext #end if
--input_model_pth_path ./input_model_pth_path.$input_model_pth_path.ext #if $input_stats_pt_path: --input_stats_pt_path ./input_stats_pt_path.$input_stats_pt_path.ext #end if #if $input_reference_pdb_path: --input_reference_pdb_path ./input_reference_pdb_path.$input_reference_pdb_path.ext #end if #if $input_ndx_path: --input_ndx_path ./input_ndx_path.$input_ndx_path.ext #end if --output_plumed_dat_path $outname_output_plumed_dat_path --output_features_dat_path $outname_output_features_dat_path --output_model_ptc_path $outname_output_model_ptc_path ;
mv $outname_output_plumed_dat_path $output_plumed_dat_path; mv $outname_output_features_dat_path $output_features_dat_path; mv $outname_output_model_ptc_path $output_model_ptc_path;
